class Solution {
public:
    int mostFrequent(vector<int>& nums, int key) {
        unordered_map<int,int> cnt;
        for (int i = 0; i + 1 < nums.size(); ++i)
            if (nums[i] == key) cnt[nums[i+1]]++;
        int best = 0, bc = 0;
        for (auto& [v, c] : cnt)
            if (c > bc) { bc = c; best = v; }
        return best;
    }
};

