class Solution {
    public int mostFrequent(int[] nums, int key) {
        int[] freq = new int[1001];
        for (int i = 0; i + 1 < nums.length; i++)
            if (nums[i] == key) freq[nums[i+1]]++;
        int best = 0;
        for (int v = 1; v <= 1000; v++)
            if (freq[v] > freq[best]) best = v;
        return best;
    }
}

